(function(){
 const allowed=new Set(['ADMIN_TOTAL']);
 const role=()=>String((typeof state!=='undefined'&&state?.profile?.rol)||'').trim().toUpperCase();
 const E=v=>typeof esc==='function'?esc(v):String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
 const isAdmin=()=>role()==='ADMIN_TOTAL';
 function actionCell(r,type){
   if(type==='missing'&&isAdmin())return `<button class="soft-btn ca-third-consult" data-plate="${E(r.placa||'')}">Consultar titular</button>`;
   if(type==='pending'&&isAdmin())return `<button class="soft-btn ca-third-confirm" data-plate="${E(r.placa||'')}" data-owner="${E(r.propietario_oficial||'')}">Confirmar 3RO</button>`;
   if(isAdmin()&&r.accion_codigo==='CERRAR_UNIDAD')return `<button class="ca78-action danger ca78-close-unit" data-unit="${E(r.unidad||'')}" data-plate="${E(r.placa||'')}" data-owner="${E(r.propietario_oficial||'')}">Cerrar unidad</button>`;
   if(isAdmin()&&r.puede_aplicar&&r.accion_codigo)return `<button class="ca78-action ${r.puede_cerrar?'danger':''} ca78-audit-apply" data-unit="${E(r.unidad||'')}" data-action="${E(r.accion_codigo||'')}" data-cupo="${E(r.cupo_ecarcheck||r.cupo_control||'')}" data-close="${r.puede_cerrar?'1':'0'}" data-plate="${E(r.placa||'')}" data-owner="${E(r.propietario_oficial||'')}">${E(r.accion||'Aplicar')}</button>`;
   return `<b>${E(r.accion||'')}</b>`;
 }
 const table=(rows,type='normal')=>`<div class="table-wrap ca77-table-wrap"><table class="pretty ca77-table"><thead><tr><th>Nivel</th><th>Galera</th><th>Unidad</th><th>Placa</th><th>Empresa</th><th>Cupo eCarcheck</th><th>Cupo Control</th><th>Propietario oficial</th><th>Acción</th><th>Motivo</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td><span class="ca-audit-badge ${String(r.nivel).toUpperCase()==='CRITICO'?'critical':''}">${E(r.nivel)}</span></td><td>${E(r.galera||'—')}</td><td><b>${E(r.unidad||'—')}</b></td><td>${E(r.placa||'—')}</td><td>${E(r.empresa||'—')}</td><td><b>${E(r.cupo_ecarcheck||'—')}</b></td><td>${E(r.cupo_control||r.cupo||'—')}</td><td>${E(r.propietario_oficial||'Sin dato')}</td><td>${actionCell(r,type)}</td><td>${E(r.motivo||'')}</td></tr>`).join(''):'<tr><td colspan="10" class="empty">Sin casos.</td></tr>'}</tbody></table></div>`;
 function thirdModal(plate,owner){
   let m=document.querySelector('#caThirdModal');if(!m){m=document.createElement('div');m.id='caThirdModal';m.className='user-modal';document.body.appendChild(m)}
   m.style.display='flex';m.innerHTML=`<div class="user-modal-card" style="max-width:620px;width:94vw"><div class="table-summary"><div><h2 style="margin:0">Confirmar vehículo 3RO</h2><span class="muted">${E(plate)} · Titular eCarcheck: ${E(owner||'Sin dato')}</span></div><button class="soft-btn" id="caThirdClose">Cerrar</button></div><div class="field"><label>Colaborador asociado (opcional)</label><input id="caThirdEmployee" placeholder="Nombre del colaborador"></div><div class="field" style="margin-top:10px"><label>Nota (opcional)</label><input id="caThirdNote" placeholder="Observación"></div><div id="caThirdMsg" style="margin-top:10px"></div><div class="actions" style="margin-top:12px"><button id="caThirdSave">Confirmar como 3RO</button></div></div>`;
   m.querySelector('#caThirdClose').onclick=()=>m.style.display='none';m.onclick=e=>{if(e.target===m)m.style.display='none'};
   m.querySelector('#caThirdSave').onclick=async()=>{const b=m.querySelector('#caThirdSave'),msg=m.querySelector('#caThirdMsg');b.disabled=true;b.textContent='Guardando...';try{const {data}=await req('/functions/v1/revisados-terceros',{method:'POST',body:JSON.stringify({action:'CONFIRMAR',placa:plate,clasificacion:'TERCERO',colaborador:m.querySelector('#caThirdEmployee').value,nota:m.querySelector('#caThirdNote').value})});if(!data?.ok)throw Error(data?.error||'No se pudo confirmar');msg.innerHTML='<div class="success">3RO confirmado y retirado de las fallas de Control de Auto.</div>';setTimeout(()=>{m.style.display='none';audit()},450)}catch(e){msg.innerHTML=`<div class="alert">${E(e.message||e)}</div>`;b.disabled=false;b.textContent='Confirmar como 3RO'}};
 }
 function actionModal(info){
   let m=document.querySelector('#ca78ActionModal');if(!m){m=document.createElement('div');m.id='ca78ActionModal';m.className='user-modal';document.body.appendChild(m)}
   const stock=info.action==='PASAR_STOCK',transfer=info.action==='PROCESAR_TRASPASO',taxi=info.action==='CAMBIAR_AMARILLO_TAXI',close=info.close,official=info.action==='REGISTRAR_CUPO'||info.action==='CORREGIR_CUPO';
   const result=official?`Cupo oficial: <b>${E(info.cupo)}</b><br>Color Control de Auto: <b>Amarillo</b>`:transfer?`El <b>cupo actual de Control</b> volverá a <b>STOCK</b>.<br>El cupo que muestra eCarcheck pertenece al nuevo titular y <b>NO se registrará</b> en el inventario del grupo.<br>La unidad quedará identificada como traspaso pendiente de cierre.`:taxi?`Color Control de Auto: <b>Amarillo</b>.<br>Se creará un pendiente en <b>Revisados</b>: anular revisado anterior + realizar nuevo <b>Revisado Taxi</b>.<br><b>No se anula automáticamente</b> ningún revisado externo.`:stock?`Cupo <b>${E(info.cupo)}</b> pasará a <b>STOCK</b>${close?'<br>La unidad quedará <b>Cerrada</b>':'<br>La unidad permanecerá <b>Activa</b>'}`:`La unidad quedará <b>Cerrada</b>`;
   m.style.display='flex';m.innerHTML=`<div class="user-modal-card ca78-modal-card"><div class="table-summary"><div><h2 style="margin:0">Confirmar cambio</h2><span class="muted">${E(info.unit)} · ${E(info.plate||'')}</span></div><button class="soft-btn" id="ca78ModalClose">Cancelar</button></div><div class="ca78-confirm-grid"><div><span>Acción</span><b>${E(info.label)}</b></div><div><span>Titular eCarcheck</span><b>${E(info.owner||'Sin dato')}</b></div></div><div class="ca78-result-box">${result}</div><div id="ca78ModalMsg"></div><div class="actions"><button id="ca78ModalApply" class="${close?'danger':''}">Confirmar</button></div></div>`;
   const cancel=()=>m.style.display='none';m.querySelector('#ca78ModalClose').onclick=cancel;m.onclick=e=>{if(e.target===m)cancel()};
   m.querySelector('#ca78ModalApply').onclick=async()=>{const b=m.querySelector('#ca78ModalApply'),msg=m.querySelector('#ca78ModalMsg');b.disabled=true;b.textContent='Aplicando...';try{
      if(info.action==='CERRAR_UNIDAD'){const {data}=await req('/functions/v1/admin-unidad-status',{method:'POST',body:JSON.stringify({unidad:info.unit,estatus:'Cerrado'})});if(!data?.ok)throw Error(data?.error||'No se pudo cerrar la unidad')}
      else {const data=await rpc('control_auto_auditoria_aplicar',{p_unidad:info.unit,p_accion:info.action,p_cupo:info.cupo||null,p_cerrar:!!info.close});if(!data?.ok)throw Error(data?.error||'No se pudo aplicar el cambio')}
      msg.innerHTML='<div class="success">Cambio aplicado y registrado en el historial.</div>';setTimeout(()=>{m.style.display='none';audit()},450)
    }catch(e){msg.innerHTML=`<div class="alert">${E(e.message||e)}</div>`;b.disabled=false;b.textContent='Confirmar'}};
 }
 async function bind(out){
   out.querySelectorAll('.ca-third-consult').forEach(b=>b.onclick=async()=>{const plate=b.dataset.plate;b.disabled=true;b.textContent='Consultando eCarcheck...';try{const {data}=await req('/functions/v1/revisados-terceros',{method:'POST',body:JSON.stringify({action:'CONSULTAR',placa:plate})});if(!data?.ok)throw Error(data?.error||'No se pudo consultar');await audit()}catch(e){b.disabled=false;b.textContent='Consultar titular';alert(e.message||e)}});
   out.querySelectorAll('.ca-third-confirm').forEach(b=>b.onclick=()=>thirdModal(b.dataset.plate,b.dataset.owner));
   out.querySelectorAll('.ca78-audit-apply').forEach(b=>b.onclick=()=>actionModal({unit:b.dataset.unit,plate:b.dataset.plate,owner:b.dataset.owner,action:b.dataset.action,cupo:b.dataset.cupo,close:b.dataset.close==='1',label:b.textContent.trim()}));
   out.querySelectorAll('.ca78-close-unit').forEach(b=>b.onclick=()=>actionModal({unit:b.dataset.unit,plate:b.dataset.plate,owner:b.dataset.owner,action:'CERRAR_UNIDAD',cupo:'',close:true,label:'Cerrar unidad'}));
 }
 async function audit(){const out=document.querySelector('#ca6Out');if(!out)return;document.querySelector('.section-tools')?.style.setProperty('display','none');out.innerHTML='<div class="card">Ejecutando auditoría de Control de Auto...</div>';try{const r=await req('/functions/v1/control-auto-auditoria',{method:'POST',body:'{}'}),d=r.data||{};if(!d.ok)throw Error(d.error||'No se pudo cargar auditoría');const k=d.kpis||{};out.innerHTML=`<div class="ca-audit-kpis ca77-audit-kpis"><div class="ca-audit-kpi"><span>Registrar cupo</span><strong>${Number(k.cupos_registrar||0)}</strong></div><div class="ca-audit-kpi"><span>Corregir cupo</span><strong>${Number(k.cupos_corregir||0)}</strong></div><div class="ca-audit-kpi"><span>Cambio de color</span><strong>${Number(k.cambios_color||0)}</strong></div><div class="ca-audit-kpi"><span>Cupo / color</span><strong>${Number(k.cupo_color_inconsistente||0)}</strong></div><div class="ca-audit-kpi"><span>Amarillo sin cupo real</span><strong>${Number(k.amarillo_sin_cupo||0)}</strong></div><div class="ca-audit-kpi"><span>Traspasos detectados</span><strong>${Number(k.traspasos_detectados||0)}</strong></div><div class="ca-audit-kpi"><span>3RO pendientes</span><strong>${Number(k.terceros_pendientes||0)}</strong></div><div class="ca-audit-kpi"><span>3RO controlados</span><strong>${Number(k.terceros_controlados||0)}</strong></div></div><section class="ca-audit-section ca77-primary"><h3>Cupos oficiales detectados en eCarcheck</h3><div class="ca-audit-note">eCarcheck informa un cupo, pero Control de Auto todavía no lo tiene registrado. Estos casos ya no se clasifican como “sin cupo”.</div>${table(d.cupos_registrar||[])}</section><section class="ca-audit-section ca80-transfer"><h3>Traspasos detectados por titular / cupo</h3><div class="ca-audit-note">El titular oficial ya no pertenece al grupo. El cupo nuevo de eCarcheck pertenece al nuevo titular y NO se registra. Si existe cupo local, vuelve a STOCK.</div>${table(d.traspasos_detectados||[])}</section><section class="ca-audit-section"><h3>Cupos que no coinciden</h3><div class="ca-audit-note">Solo aparecen aquí diferencias de cupo donde el titular oficial todavía pertenece al grupo. En ese escenario sí corresponde corregir la asignación local.</div>${table(d.cupos_corregir||[])}</section><section class="ca-audit-section"><h3>Cupos liberados o posibles traspasos</h3><div class="ca-audit-note">Control de Auto conserva un cupo que eCarcheck ya no informa. El titular oficial define si el cupo vuelve a STOCK manteniendo la unidad activa, o si además corresponde cerrar la unidad.</div>${table(d.cupos_local_sin_ecarcheck||[])}</section><section class="ca-audit-section"><h3>Cambios de color detectados</h3><div class="ca-audit-note">eCarcheck es la fuente oficial del color. Plata y Plateado se consideran el mismo color. Si el nuevo color oficial es Amarillo, la acción también crea el pendiente legal de Revisado Taxi.</div>${table(d.cambios_color||[])}</section><section class="ca-audit-section"><h3>Cupo oficial con color no amarillo</h3><div class="ca-audit-note">eCarcheck informa un cupo, pero su mismo color oficial no es amarillo. Requiere revisión.</div>${table(d.cupo_color_inconsistente||[])}</section><section class="ca-audit-section"><h3>Amarillo sin cupo real</h3><div class="ca-audit-note">No requiere acción mientras el titular siga perteneciendo al grupo. La unidad permanece activa en espera de que el traspaso se refleje oficialmente.</div>${table(d.amarillo_sin_cupo||[])}</section><section class="ca-audit-section"><h3>Validar traspaso</h3><div class="ca-audit-note">Amarillo sin cupo y cuyo titular oficial no corresponde a las empresas del grupo.</div>${table(d.validar_traspaso||[])}</section><section class="ca-audit-section"><h3>Validar propietario</h3>${table(d.sin_propietario||[])}</section><section class="ca-audit-section"><h3>Placas sin Control de Auto</h3><div class="ca-audit-note">Primero se consulta el titular en eCarcheck. Luego se decide si es 3RO o una unidad que realmente falta en Control.</div>${table([...(d.sin_placa||[]),...(d.ecarcheck_sin_control||[])],'missing')}</section><section class="ca-audit-section"><h3>3RO por confirmar</h3>${table(d.terceros_pendientes||[],'pending')}</section><section class="ca-audit-section"><h3>3RO controlados</h3><div class="ca-audit-note">Vehículos de colaboradores/terceros confirmados. No forman parte de la flota ni de los indicadores de cupos.</div>${table(d.terceros_controlados||[],'controlled')}</section>`;await bind(out)}catch(e){out.innerHTML=`<div class="alert">Auditoría: ${E(e.message||e)}</div>`}}
 (window.__RYM_CONTROL_PENDING_AFTER__ ||= []).push(['unidades',async function(){if(!allowed.has(role()))return;const tabs=document.querySelector('.ca6-tabs');if(!tabs||document.querySelector('#ca6Audit'))return;const b=document.createElement('button');b.id='ca6Audit';b.className='soft-btn';b.textContent='Auditoría';tabs.appendChild(b);b.onclick=()=>{tabs.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');audit()};['ca6Active','ca6Other'].forEach(id=>{const x=document.querySelector('#'+id);if(x)x.addEventListener('click',()=>document.querySelector('.section-tools')?.style.removeProperty('display'))})}]);
})();
